// friday13.cs
// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count how many occur in a full 400-year cycle.

// Earliest Friday the 13th
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var candidate = new DateTime(year, month, 13);
        if (candidate.DayOfWeek == DayOfWeek.Friday)
        {
            earliest ??= candidate;
            break;
        }
    }
    if (earliest != null) break;
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest!.Value.DayOfWeek})");

// Count all Friday the 13ths in a 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
EOF
